import { Suspense } from 'react';
import { Container, Nav, Navbar } from 'react-bootstrap';
import { Navigate, NavLink, Route, Routes } from 'react-router-dom';
import StudentArea from './components/StudentArea';
import { BookingProvider, useBookings } from './context/BookingContext';
import { StudentProvider } from './context/StudentContext';
import { useSelector } from 'react-redux';
import { ROOMS } from './data/seed';
import { selectBusiestRoom } from './store/selectors';
import RoomsPage from './pages/RoomsPage';
import { lazyWithPreload, withDelay } from './utils/lazy';

// trang danh sách (trang mở đầu) giữ trong bundle chính; hai trang còn lại tách chunk
const RoomPage = lazyWithPreload(withDelay(() => import('./pages/RoomPage'), 400));
const MyBookingsPage = lazyWithPreload(withDelay(() => import('./pages/MyBookingsPage'), 400));

function Shell() {
  const { bookings, status, error, reload } = useBookings();
  const busiest = useSelector(selectBusiestRoom);
  return (
    <>
      <Navbar bg="primary" variant="dark" expand="md" id="app-nav">
        <Container>
          <Navbar.Brand id="title">CT Booking</Navbar.Brand>
          <Nav className="me-auto">
            <Nav.Link as={NavLink} to="/rooms" id="nav-rooms">Rooms</Nav.Link>
            <Nav.Link as={NavLink} to="/my-bookings" id="nav-my" onMouseEnter={MyBookingsPage.preload} onFocus={MyBookingsPage.preload}>My bookings</Nav.Link>
          </Nav>
          <Navbar.Text id="summary" className="text-white me-3">{ROOMS.length} rooms · {bookings.length} bookings today</Navbar.Text>
          <StudentArea />
        </Container>
      </Navbar>
      <Container className="py-4">
        {status === 'ready' && (
          <p id="stats" className="text-muted">{busiest ? `Busiest room: ${busiest.name} (${busiest.count} bookings)` : 'No bookings yet today'}</p>
        )}
        {status === 'loading' && <p id="bookings-loading" className="text-muted">Loading bookings…</p>}
        {status === 'error' && (
          <div>
            <p id="bookings-error" className="error">Could not load bookings ({error})</p>
            <button id="retry" type="button" className="btn btn-outline-danger btn-sm" onClick={reload}>Retry</button>
          </div>
        )}
        {status === 'ready' && (
        <Suspense fallback={<p id="page-loading" className="text-muted">Loading page…</p>}>
        <Routes>
          <Route path="/" element={<Navigate to="/rooms" replace />} />
          <Route path="/rooms" element={<RoomsPage />} />
          <Route path="/rooms/:id" element={<RoomPage />} />
          <Route path="/my-bookings" element={<MyBookingsPage />} />
          <Route path="*" element={<p id="page-404">Page not found</p>} />
        </Routes>
        </Suspense>
        )}
      </Container>
    </>
  );
}

export default function App() {
  return (
    <StudentProvider>
      <BookingProvider>
        <Shell />
      </BookingProvider>
    </StudentProvider>
  );
}
